"""Freeze an editor handoff, never a judge packet or approval."""
from pathlib import Path
import hashlib,json,ast
BASE=Path(__file__).resolve().parent;OBJ=BASE.parent;ROUND=OBJ/'candidates/round-01';DEL=OBJ/'delivery'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def record(p):return {'path':p.relative_to(OBJ).as_posix(),'sha256':sha(p),'relativeTo':'experiment'}
