files=sorted([p for p in [*BASE.rglob('*'),*ROUND.rglob('*')] if p.is_file() and '__pycache__' not in p.parts])
assert all(p.stat().st_size<100000000 for p in files)
for p in BASE.glob('*.py'):ast.parse(p.read_text())
manifest=DEL/'resource-manifest-round-01.json'
